public String toString(int index, boolean standardConformingStrings) {
  --index;
  if (paramValues[index] == null) {
    return "?";
  } else if (paramValues[index] == NULL_OBJECT) {
    return "NULL";
  }
  String textValue;
  String type;
  if ((flags[index] & BINARY) == BINARY) {
    // handle some of the numeric types
    switch (paramTypes[index]) {
      case Oid.INT2:
        short s = ByteConverter.int2((byte[]) paramValues[index], 0);
        textValue = Short.toString(s);
        type = "int2";
        break;

      case Oid.INT4:
        int i = ByteConverter.int4((byte[]) paramValues[index], 0);
        textValue = Integer.toString(i);
        type = "int4";
        break;

      case Oid.INT8:
        long l = ByteConverter.int8((byte[]) paramValues[index], 0);
        textValue = Long.toString(l);
        type = "int8";
        break;

      case Oid.FLOAT4:
        float f = ByteConverter.float4((byte[]) paramValues[index], 0);
        if (Float.isNaN(f)) {
          return "'NaN'::real";
        }
        textValue = Float.toString(f);
        type = "real";
        break;

      case Oid.FLOAT8:
        double d = ByteConverter.float8((byte[]) paramValues[index], 0);
        if (Double.isNaN(d)) {
          return "'NaN'::double precision";
        }
        textValue = Double.toString(d);
        type = "double precision";
        break;

      case Oid.UUID:
        textValue =
            new UUIDArrayAssistant().buildElement((byte[]) paramValues[index], 0, 16).toString();
        type = "uuid";
        break;

      case Oid.POINT:
        RedshiftPoint pgPoint = new RedshiftPoint();
        pgPoint.setByteValue((byte[]) paramValues[index], 0);
        textValue = pgPoint.toString();
        type = "point";
        break;

      case Oid.BOX:
        RedshiftBox pgBox = new RedshiftBox();
        pgBox.setByteValue((byte[]) paramValues[index], 0);
        textValue = pgBox.toString();
        type = "box";
        break;

      default:
        return "?";
    }
  } else {
    textValue = paramValues[index].toString();
    int paramType = paramTypes[index];

    if (paramType == Oid.TIMESTAMP) {
      type = "timestamp";
    } else if (paramType == Oid.TIMESTAMPTZ) {
      type = "timestamp with time zone";
    } else if (paramType == Oid.TIME) {
      type = "time";
    } else if (paramType == Oid.TIMETZ) {
      type = "time with time zone";
    } else if (paramType == Oid.DATE) {
      type = "date";
    } else if (paramType == Oid.INTERVAL) {
      type = "interval";
    } else if (paramType == Oid.INTERVALY2M) {
      type = "interval year to month";
    } else if (paramType == Oid.INTERVALD2S) {
      type = "interval day to second";
    } else if (paramType == Oid.NUMERIC) {
      type = "numeric";
    }
    else {
      type = null;
    }
  }
  return quoteAndCast(textValue, type, standardConformingStrings);
}

public String toString(int index, boolean standardConformingStrings) {
  --index;
  if (paramValues[index] == null) {
    return "?";
  } else if (paramValues[index] == NULL_OBJECT) {
    return "NULL";
  }
  String textValue;
  String type;
  if ((flags[index] & BINARY) == BINARY) {
    // handle some of the numeric types
    switch (paramTypes[index]) {
      case Oid.INT2:
        short s = ByteConverter.int2((byte[]) paramValues[index], 0);
        textValue = Short.toString(s);
        type = "int2";
        break;

      case Oid.INT4:
        int i = ByteConverter.int4((byte[]) paramValues[index], 0);
        textValue = Integer.toString(i);
        type = "int4";
        break;

      case Oid.INT8:
        long l = ByteConverter.int8((byte[]) paramValues[index], 0);
        textValue = Long.toString(l);
        type = "int8";
        break;

      case Oid.FLOAT4:
        float f = ByteConverter.float4((byte[]) paramValues[index], 0);
        if (Float.isNaN(f)) {
          return "'NaN'::real";
        }
        textValue = Float.toString(f);
        type = "real";
        break;

      case Oid.FLOAT8:
        double d = ByteConverter.float8((byte[]) paramValues[index], 0);
        if (Double.isNaN(d)) {
          return "'NaN'::double precision";
        }
        textValue = Double.toString(d);
        type = "double precision";
        break;

      case Oid.UUID:
        textValue =
            new UUIDArrayAssistant().buildElement((byte[]) paramValues[index], 0, 16).toString();
        type = "uuid";
        break;

      case Oid.POINT:
        RedshiftPoint pgPoint = new RedshiftPoint();
        pgPoint.setByteValue((byte[]) paramValues[index], 0);
        textValue = pgPoint.toString();
        type = "point";
        break;

      case Oid.BOX:
        RedshiftBox pgBox = new RedshiftBox();
        pgBox.setByteValue((byte[]) paramValues[index], 0);
        textValue = pgBox.toString();
        type = "box";
        break;

      default:
        return "?";
    }
  } else {
    textValue = paramValues[index].toString();
    int paramType = paramTypes[index];

    switch (paramTypes[index])
    {
      case Oid.INT2:
        type = "int2";
        break;
      case Oid.INT4:
        type = "int4";
        break;
      case Oid.INT8:
        type = "int8";
        break;
      case Oid.FLOAT4:
        type = "real";
        break;
      case Oid.FLOAT8:
        type = "double precision";
        break;
      case Oid.TIMESTAMP:
        type = "timestamp";
        break;
      case Oid.TIMESTAMPTZ:
        type = "timestamp with time zone";
        break;
      case Oid.TIME:
        type = "time";
        break;
      case Oid.TIMETZ:
        type = "time with time zone";
        break;
      case Oid.DATE:
        type = "date";
        break;
      case Oid.INTERVAL:
        type = "interval";
        break;
      case Oid.INTERVALY2M:
        type = "interval year to month";
        break;
      case Oid.INTERVALD2S:
        type = "interval day to second";
        break;
      case Oid.NUMERIC:
        type = "numeric";
        break;
      case Oid.UUID:
        type = "uuid";
        break;
      case Oid.BOOL:
        type = "boolean";
        break;
      case Oid.BOX:
        type = "box";
        break;
      case Oid.POINT:
        type = "point";
        break;
      default:
        type = null;
    }
  }
  return quoteAndCast(textValue, type, standardConformingStrings);
}

public SecurityFilterChain configureAPISecurityFilterChain(HttpSecurity http) throws Exception {
   log.info("Starting security configuration for APIs");

   // State-less session (state in access-token only)
   http.sessionManagement(sm -> sm.sessionCreationPolicy(SessionCreationPolicy.STATELESS));

   // Disable CSRF because of state-less session-management
   http.csrf(csrf -> csrf.disable());

   // Disable CORS as we already have a filter in WebConfiguration that does the job
   http.cors(cors -> cors.disable());
   if (Boolean.TRUE.equals(keycloakEnabled)) {
      log.info("Keycloak is enabled, configuring oauth2 & request authorization");

      http.authorizeHttpRequests(registry -> registry
            .requestMatchers("/api/services", "/api/services/*", "/api/jobs", "/api/jobs/*")
            .hasAnyRole(ROLE_USER, ROLE_MANAGER, ROLE_ADMIN).requestMatchers("/api/services/*/*")
            .hasAnyRole(ROLE_MANAGER, ROLE_ADMIN).requestMatchers("/api/jobs/*/*")
            .hasAnyRole(ROLE_MANAGER, ROLE_ADMIN).requestMatchers("/api/artifact/*").hasAnyRole(ROLE_ADMIN)
            .requestMatchers("/api/import", "/api/export").hasAnyRole(ROLE_ADMIN)
            .requestMatchers(HttpMethod.GET, "/api/secrets").hasAnyRole(ROLE_USER, ROLE_MANAGER, ROLE_ADMIN)
            .requestMatchers(HttpMethod.GET, "/api/secrets/*").hasAnyRole(ROLE_USER, ROLE_MANAGER, ROLE_ADMIN)
            .requestMatchers(HttpMethod.POST, "/api/secrets").hasAnyRole(ROLE_ADMIN)
            .requestMatchers(HttpMethod.PUT, "/api/secrets/*").hasAnyRole(ROLE_ADMIN)
            .requestMatchers(HttpMethod.DELETE, "/api/secrets/*").hasAnyRole(ROLE_ADMIN).anyRequest().permitAll());

      http.oauth2ResourceServer(oauth2Configurer -> oauth2Configurer
            .jwt(jwtConfigurer -> jwtConfigurer.jwtAuthenticationConverter(new MicrocksJwtConverter())));
   } else {
      log.info("Keycloak is disabled, permitting all requests");
      http.authorizeHttpRequests(registry -> registry.anyRequest().permitAll());
   }

   // Disable the publication of X-Frame-Options to allow embedding the UI.
   // See https://github.com/microcks/microcks/issues/952
   http.headers(headers -> headers.frameOptions(HeadersConfigurer.FrameOptionsConfig::disable));

   return http.build();
}

