public static boolean install(Context context) {
    try {
        // Try installing new SSL provider from Google Play Service
        Context gms = context.createPackageContext("com.google.android.gms",
                Context.CONTEXT_INCLUDE_CODE | Context.CONTEXT_IGNORE_SECURITY);
        gms.getClassLoader()
                .loadClass("com.google.android.gms.common.security.ProviderInstallerImpl")
                .getMethod("insertProvider", Context.class)
                .invoke(null, gms);
    } catch (Exception e) {
        return false;
    }
    return true;
}

public static boolean install(Context context) {
    try {
        // Check if gms is a system app
        ApplicationInfo appInfo = context.getPackageManager().getApplicationInfo(GMS_PACKAGE_NAME, 0);
        if ((appInfo.flags & ApplicationInfo.FLAG_SYSTEM) == 0) {
            return false;
        }

        // Try installing new SSL provider from Google Play Service
        Context gms = context.createPackageContext(GMS_PACKAGE_NAME,
                Context.CONTEXT_INCLUDE_CODE | Context.CONTEXT_IGNORE_SECURITY);
        gms.getClassLoader()
                .loadClass("com.google.android.gms.common.security.ProviderInstallerImpl")
                .getMethod("insertProvider", Context.class)
                .invoke(null, gms);
    } catch (Exception e) {
        return false;
    }
    return true;
}

private static Element buildScripTag(String content, String type, String id, String param) {
        var encodedContent = UriUtils.encodeFragment(content, StandardCharsets.UTF_8);
        var e = new Element("script");
        e.appendChild(new Text(encodedContent));
        e.setAttribute("type", type);
        e.setAttribute("id", id);
        if (param != null) {
            e.setAttribute("data-param", param);
