private List<RequiredRightAnalysisResult> analyzeWithExceptions(MacroBlock macroBlock)
        throws RequiredRightsException
    {
        List<RequiredRightAnalysisResult> result;

        Optional<RequiredRightAnalyzer<MacroBlock>>
            specificAnalyzer = getMacroBlockRequiredRightAnalyzer(macroBlock);

        if (specificAnalyzer.isPresent()) {
            result = specificAnalyzer.get().analyze(macroBlock);
        } else {
            // Check if there is a macro analyzer for this macro, if yes, use it.
            Optional<MacroRequiredRightsAnalyzer> macroAnalyzer = getMacroAnalyzer(macroBlock.getId());

            if (macroAnalyzer.isPresent()) {
                DefaultMacroRequiredRightReporter reporter = this.macroRequiredRightReporterProvider.get();
                macroAnalyzer.get().analyze(macroBlock, reporter);
                result = reporter.getResults();
            } else {
                // No specific analyzer found, get more information about the macro.
                Macro<?> macro = getMacro(macroBlock);

                if (macro instanceof ScriptMacro) {
                    result = this.scriptMacroAnalyzer.analyze(macroBlock);
                } else if (macro != null) {
                    result = new ArrayList<>(maybeAnalyzeMacroContent(macroBlock, macro));
                    result.addAll(maybeAnalyzeParameters(macroBlock, macro));
                } else {
                    result = List.of();
                }
            }
        }

        return result;
    }

private List<RequiredRightAnalysisResult> analyzeWithExceptions(MacroBlock macroBlock)
        throws RequiredRightsException
    {
        List<RequiredRightAnalysisResult> result;

        Optional<RequiredRightAnalyzer<MacroBlock>>
            specificAnalyzer = getMacroBlockRequiredRightAnalyzer(macroBlock);

        if (specificAnalyzer.isPresent()) {
            result = specificAnalyzer.get().analyze(macroBlock);
        } else {
            // Check if there is a macro analyzer for this macro, if yes, use it.
            Optional<MacroRequiredRightsAnalyzer> macroAnalyzer = getMacroAnalyzer(macroBlock.getId());

            if (macroAnalyzer.isPresent()) {
                DefaultMacroRequiredRightReporter reporter = this.macroRequiredRightReporterProvider.get();
                macroAnalyzer.get().analyze(macroBlock, reporter);
                result = reporter.getResults();
            } else {
                // No specific analyzer found, get more information about the macro.
                Macro<?> macro = getMacro(macroBlock);

                if (macro instanceof ScriptMacro) {
                    result = this.scriptMacroAnalyzer.analyze(macroBlock);
                } else if (macro != null && this.shouldMacroContentBeParsed(macro)) {
                    result = analyzeMacroContent(macroBlock, macroBlock.getContent());
                } else {
                    result = List.of();
                }
            }
        }

        return result;
    }

@Override
    public void analyze(MacroBlock macroBlock, MacroRequiredRightReporter reporter)
    {
        ContextMacroParameters parameters = new ContextMacroParameters();

        try {
            this.beanManager.populate(parameters, macroBlock.getParameters());

            // If the source parameter is set, the content is ignored, and we should analyze the source parameter
            // instead.
            if (parameters.getSource() != null) {
                String sourceType = parameters.getSource().getType();

                switch (sourceType) {
                    case MacroContentSourceReference.TYPE_STRING:
                        if (!parameters.isRestricted()) {
                            reporter.analyzeContent(macroBlock, parameters.getSource().getReference());
                        }
                        break;

                    case MacroContentSourceReference.TYPE_SCRIPT:
                        if (parameters.isRestricted()) {
                            reporter.report(macroBlock, List.of(MacroRequiredRight.SCRIPT),
                                "rendering.macro.context.requiredRights.restrictedScriptSource");
                        } else {
                            // We don't know the actual content, but at least script right is needed and the content
                            // could contain anything, so it might require programming right.
                            reporter.report(macroBlock,
                                List.of(MacroRequiredRight.SCRIPT, MacroRequiredRight.MAYBE_PROGRAM),
                                "rendering.macro.context.requiredRights.arbitraryScriptSource");
                        }
                        break;

                    default:
                        // Do nothing.
                }
            } else if (!parameters.isRestricted()) {
                reporter.analyzeContent(macroBlock, macroBlock.getContent());
            }
        } catch (PropertyException e) {
            // Ignore, the macro won't be executed when populating the parameters fails.
        }
    }

@Override
    public void analyze(MacroBlock macroBlock, MacroRequiredRightReporter reporter)
    {
        ContextMacroParameters parameters = new ContextMacroParameters();

        try {
            this.beanManager.populate(parameters, macroBlock.getParameters());

            // Analyze the content only when it isn't restricted.
            if (!parameters.isRestricted()) {
                reporter.analyzeContent(macroBlock, macroBlock.getContent());
            }
        } catch (PropertyException e) {
            // Ignore, the macro won't be executed when populating the parameters fails.
        }
    }

public String escapeRedirect(String url) {
	if (Validator.isNull(url)) {
		return url;
	}

	if (url.contains(_UNICODE_REPLACEMENT_CHARACTER)) {
		return null;
	}

	URI uri = null;

	try {
		uri = HttpComponentsUtil.getURI(url);
	}
	catch (URISyntaxException uriSyntaxException) {
		if (_log.isDebugEnabled()) {
			_log.debug(uriSyntaxException);
		}
	}

	if (uri == null) {
		return null;
	}

	if (!uri.isAbsolute()) {

		// https://datatracker.ietf.org/doc/html/rfc3986#section-4.2

		url = url.trim();

		if (url.startsWith(StringPool.DOUBLE_SLASH)) {

			// "//" authority path-abempty

			return null;
		}

		return url;
	}

	long companyId = CompanyThreadLocal.getCompanyId();

	String[] allowedProtocols = RedirectURLSettingsUtil.getAllowedProtocols(
		companyId);

	if ((allowedProtocols.length != 0) &&
		!ArrayUtil.contains(allowedProtocols, uri.getScheme(), true)) {

		return null;
	}

	String domain = uri.getHost();

	if (Validator.isNull(domain)) {

		// Absolute URL must have a domain

		return null;
	}

	if (!_validPortalDomainCheckDisabled && isValidPortalDomain(domain)) {
		return url;
	}

	String securityMode = RedirectURLSettingsUtil.getSecurityMode(
		companyId);

	if (securityMode.equals("domain")) {
		String[] allowedDomains = RedirectURLSettingsUtil.getAllowedDomains(
			companyId);

		if (allowedDomains.length == 0) {
			return url;
		}

		for (String allowedDomain : allowedDomains) {
			if (allowedDomain.startsWith("*.") &&
				(allowedDomain.regionMatches(
					1, domain,
					domain.length() - (allowedDomain.length() - 1),
					allowedDomain.length() - 1) ||
				 allowedDomain.regionMatches(
					 2, domain, 0, domain.length()))) {

				return url;
			}
			else if (allowedDomain.equals(domain)) {
				return url;
			}
			else if (allowedDomain.equals("PORTAL_DOMAINS")) {
				if (Validator.isNotNull(
						VirtualHostLocalServiceUtil.fetchVirtualHost(
							domain))) {

					return url;
				}

				ServiceContext serviceContext =
					ServiceContextThreadLocal.getServiceContext();

				ThemeDisplay themeDisplay =
					serviceContext.getThemeDisplay();

				if (domain.equals(themeDisplay.getPortalDomain())) {
					return url;
				}
			}
		}

		if (_log.isWarnEnabled()) {
			_log.warn("Redirect URL " + url + " is not allowed");
		}

		url = null;
	}
	else {
		String[] allowedIPs = RedirectURLSettingsUtil.getAllowedIPs(
			companyId);

		if (allowedIPs.length == 0) {
			return url;
		}

		try {
			InetAddress inetAddress = InetAddressUtil.getInetAddressByName(
				domain);

			String hostAddress = inetAddress.getHostAddress();

			boolean serverIpIsHostAddress = _computerAddresses.contains(
				hostAddress);

			for (String ip : allowedIPs) {
				if ((serverIpIsHostAddress && ip.equals("SERVER_IP")) ||
					ip.equals(hostAddress)) {

					return url;
				}
			}

			if (_log.isWarnEnabled()) {
				_log.warn("Redirect URL " + url + " is not allowed");
			}
		}
		catch (UnknownHostException unknownHostException) {
			if (_log.isDebugEnabled()) {
				_log.debug(
					"Unable to determine IP for redirect URL " + url,
					unknownHostException);
			}
		}

		url = null;
	}

	return url;
}

public String escapeRedirect(String url) {
	if (Validator.isNull(url)) {
		return url;
	}

	if (url.contains(_UNICODE_REPLACEMENT_CHARACTER)) {
		return null;
	}

	URI uri = null;

	try {
		uri = HttpComponentsUtil.getURI(url);
	}
	catch (URISyntaxException uriSyntaxException) {
		if (_log.isDebugEnabled()) {
			_log.debug(uriSyntaxException);
		}
	}

	if (uri == null) {
		return null;
	}

	if (!uri.isAbsolute()) {

		// https://datatracker.ietf.org/doc/html/rfc3986#section-4.2

		url = url.trim();

		if (url.startsWith(StringPool.DOUBLE_SLASH)) {

			// "//" authority path-abempty

			return null;
		}

		return url;
	}

	String domain = uri.getHost();

	if (Validator.isNull(domain)) {

		// Absolute URL must have a domain

		return null;
	}

	if (!_validPortalDomainCheckDisabled && isValidPortalDomain(domain)) {
		return url;
	}

	long companyId = CompanyThreadLocal.getCompanyId();

	String securityMode = RedirectURLSettingsUtil.getSecurityMode(
		companyId);

	if (securityMode.equals("domain")) {
		String[] allowedDomains = RedirectURLSettingsUtil.getAllowedDomains(
			companyId);

		if (allowedDomains.length == 0) {
			return url;
		}

		for (String allowedDomain : allowedDomains) {
			if (allowedDomain.startsWith("*.") &&
				(allowedDomain.regionMatches(
					1, domain,
					domain.length() - (allowedDomain.length() - 1),
					allowedDomain.length() - 1) ||
				 allowedDomain.regionMatches(
					 2, domain, 0, domain.length()))) {

				return url;
			}
			else if (allowedDomain.equals(domain)) {
				return url;
			}
			else if (allowedDomain.equals("PORTAL_DOMAINS")) {
				if (Validator.isNotNull(
						VirtualHostLocalServiceUtil.fetchVirtualHost(
							domain))) {

					return url;
				}

				ServiceContext serviceContext =
					ServiceContextThreadLocal.getServiceContext();

				ThemeDisplay themeDisplay =
					serviceContext.getThemeDisplay();

				if (domain.equals(themeDisplay.getPortalDomain())) {
					return url;
				}
			}
		}

		if (_log.isWarnEnabled()) {
			_log.warn("Redirect URL " + url + " is not allowed");
		}

		url = null;
	}
	else {
		String[] allowedIPs = RedirectURLSettingsUtil.getAllowedIPs(
			companyId);

		if (allowedIPs.length == 0) {
			return url;
		}

		try {
			InetAddress inetAddress = InetAddressUtil.getInetAddressByName(
				domain);

			String hostAddress = inetAddress.getHostAddress();

			boolean serverIpIsHostAddress = _computerAddresses.contains(
				hostAddress);

			for (String ip : allowedIPs) {
				if ((serverIpIsHostAddress && ip.equals("SERVER_IP")) ||
					ip.equals(hostAddress)) {

					return url;
				}
			}

			if (_log.isWarnEnabled()) {
				_log.warn("Redirect URL " + url + " is not allowed");
			}
		}
		catch (UnknownHostException unknownHostException) {
			if (_log.isDebugEnabled()) {
				_log.debug(
					"Unable to determine IP for redirect URL " + url,
					unknownHostException);
			}
		}

		url = null;
	}

	return url;
}

