public final void write(byte[] b, int off, int len) throws IOException {
	// Sanity check
	if (b == null) {
		throw new NullPointerException();
	}

	// Comprehensive bounds checking to prevent integer overflow
	if (off < 0 || len < 0 || len > b.length || off > b.length - len) {
		throw new ArrayIndexOutOfBoundsException();
	}

	try {
		fileSystemManager.checkQuota(len);
		super.write(b, off, len);
	} catch (IOException e) {
		try {
			close();
		} catch (IOException ignore) {
		}
		throw e;
	}
}

public final void write(byte[] b, int off, int len) throws IOException {
	if (len < 0) {
		throw new IndexOutOfBoundsException();
	}
	try {
		fileSystemManager.checkQuota(len);
		super.write(b, off, len);
	} catch (IOException e) {
		try {
			close();
		} catch (IOException ignored) {}
		throw e;
	}
}

public void write(byte[] b, int off, int len) throws IOException {
    // Validate input parameters
    if (b == null) {
        throw new NullPointerException("Input byte array cannot be null");
    }

    if (off < 0 || len < 0 || off + len > b.length) {
        throw new ArrayIndexOutOfBoundsException("Invalid offset or length parameters");
    }

    // Only perform the write operation after validation
    this.ops.write(b, off, len);
}

public void write(byte[] b, int off, int len) throws IOException {
	this.ops.write(b, off, len);
}
